function Read-ObjBytes([string]$h) {
  $obj = Join-Path (Get-Location) (".git\objects\" + $h.Substring(0,2) + "\" + $h.Substring(2));
  $fs = [System.IO.File]::OpenRead($obj); $fs.Position = 2;
  $ds = New-Object System.IO.Compression.DeflateStream($fs, [System.IO.Compression.CompressionMode]::Decompress);
  $ms = New-Object System.IO.MemoryStream; $ds.CopyTo($ms); $ds.Dispose(); $fs.Dispose();
  return $ms.ToArray();
}
function FindInTree([string]$treeSha, [string[]]$pathParts) {
  $raw = Read-ObjBytes $treeSha;
  $nul = [Array]::IndexOf($raw, [byte]0);
  $data = New-Object byte[] ($raw.Length - $nul - 1);
  [Array]::Copy($raw, $nul+1, $data, 0, $data.Length);
  $pos = 0;
  while ($pos -lt $data.Length) {
    $sp=-1; for($k=$pos;$k -lt $data.Length;$k++){ if($data[$k]-eq 32){$sp=$k;break} }
    $nul2=-1; for($k=$sp+1;$k -lt $data.Length;$k++){ if($data[$k]-eq 0){$nul2=$k;break} }
    $mode=[System.Text.Encoding]::ASCII.GetString($data,$pos,$sp-$pos);
    $name=[System.Text.Encoding]::UTF8.GetString($data,$sp+1,$nul2-$sp-1);
    $sb=New-Object byte[] 20; [Array]::Copy($data,$nul2+1,$sb,0,20);
    $sha=($sb|ForEach-Object{$_.ToString('x2')})-join '';
    if ($name -eq $pathParts[0]) { if($pathParts.Length-eq 1){return "$mode $sha"}; if($mode-eq'40000'){return FindInTree $sha ($pathParts[1..($pathParts.Length-1)])} }
    $pos=$nul2+21;
  }
  return "NOT_FOUND";
}
